    };

    const onDeath = (): void => {
      const previous = ctx.state.getState();
      const lives = Math.max(0, previous.lives - 1);
      const deaths = previous.deaths + 1;
      ctx.state.set({
        deaths,
        gameOver: lives === 0 ? 1 : 0,
        lives,
        phase: lives === 0 ? "lost" : "dead",
      });
      emitPlaytestEvent({ entity: "player", name: "died", lives });
      if (lives === 0) return;
