  #detectedPlayer = false;
  #fireTimer = 0;
  #onFire: (origin: Vector3, direction: Vector3) => void;
  #scanHandle: ScheduleHandle | undefined;
  readonly rifle: Group;

  constructor(
    ctx: GameCtx,
    materials: Parameters<typeof createEnemyVisual>[0],
    patrolWaypoints: Vector3[],
    options: {
      readonly health?: number;
      readonly onFire?: (origin: Vector3, direction: Vector3) => void;
    } = {},
  ) {
    this.health = options.health ?? 50;
    this.#onFire = options.onFire ?? (() => undefined);
    this.#patrolWaypoints = patrolWaypoints.length > 0 ? patrolWaypoints : [new Vector3(0, 0.85, 0)];

    this.mesh = createEnemyVisual(materials);
    const firstWaypoint = this.#patrolWaypoints[0];
    this.mesh.position.copy(firstWaypoint ?? new Vector3(0, 0.85, 0));
    ctx.add(this.mesh);

    this.body = new CharacterBody3D({
      collisionLayer: HOSTILE_LAYER,
      collisionMask: WORLD_LAYER | PLAYER_LAYER,
      autostep: { maxHeight: 0.25, minWidth: 0.18 },
      object: this.mesh,
      physics: ctx.physics,
      shape: CollisionShape3D.capsule(0.4, 0.35),
    });

    this.rifle = createRifleVisual(materials);
    this.mesh.add(this.rifle);
    this.rifle.position.set(0.35, 0.45, 0);
  }

  startScanning(ctx: GameCtx, playerMesh: Group): void {
    const scan = (): void => {
      if (!this.alive) return;
      const distance = this.mesh.position.distanceTo(playerMesh.position);

      if (distance < DETECTION_RANGE) {
        const dirToPlayer = playerMesh.position
          .clone()
          .sub(this.mesh.position)
          .normalize();
        const forward = new Vector3(0, 0, -1);
        forward.applyAxisAngle(new Vector3(0, 1, 0), this.mesh.rotation.y);
        const angle = Math.acos(Math.max(-1, Math.min(1, dirToPlayer.dot(forward))));
        this.#detectedPlayer = angle < Math.PI / 3;
      } else {
        this.#detectedPlayer = false;
      }
      this.#scanHandle = ctx.after(ctx.random.range(3, 8) / 60, scan);
    };
    this.#scanHandle = ctx.after(ctx.random.range(3, 8) / 60, scan);
  }

  update(ctx: GameCtx, dt: number, playerMesh: Group): void {
    if (!this.alive) return;

    const targetWaypoint = this.#patrolWaypoints[this.#patrolIndex] ?? this.#patrolWaypoints[0] ?? new Vector3(0, 0.85, 0);
    const targetPosition = this.#detectedPlayer ? playerMesh.position.clone() : targetWaypoint.clone();

    if (!this.#detectedPlayer) {
      const distance = this.mesh.position.distanceTo(targetPosition);
      if (distance < 0.5) {
        this.#patrolIndex = (this.#patrolIndex + 1) % this.#patrolWaypoints.length;
      }
    }

    const direction = targetPosition.sub(this.mesh.position);
    const distance = direction.length();
    const speed = this.#detectedPlayer ? CHASE_SPEED : PATROL_SPEED;

    if (distance > 0.1) {
      direction.normalize();
      this.mesh.rotation.y = Math.atan2(direction.x, -direction.z);
      this.body.velocity.x = direction.x * speed;
      this.body.velocity.z = direction.z * speed;
    } else {
      this.body.velocity.x = 0;
      this.body.velocity.z = 0;
    }

    this.body.moveAndSlide(dt);

    if (this.#detectedPlayer) {
      this.#fireTimer -= dt;
      if (this.#fireTimer <= 0) {
        this.#fireTimer = FIRE_COOLDOWN;
        const muzzlePos = this.mesh.position.clone().add(new Vector3(0.4, 0.55, 0));
        const fireDir = playerMesh.position
          .clone()
          .sub(muzzlePos)
          .normalize();
        this.#onFire(muzzlePos, fireDir);
      }
    }
  }

  takeDamage(amount: number): boolean {
    if (!this.alive || !Number.isFinite(amount) || amount <= 0) return false;
    this.health = Math.max(0, this.health - amount);
    if (this.health > 0) return false;
    this.alive = false;
    this.mesh.visible = false;
    this.body.velocity.set(0, 0, 0);
    return true;
  }

  debug(): Record<string, unknown> {
    return {
      alive: this.alive,
      detected: this.#detectedPlayer,
      health: this.health,
      position: this.mesh.position.toArray(),
    };
  }

  dispose(): void {
    this.#scanHandle?.cancel();
    this.body.dispose();
    this.mesh.removeFromParent();
  }
}

