export function createEnemyVisual(materials: ShooterMaterials): Group {
  const group = new Group();
  group.name = "enemy-visual";
  const body = block(0.68, 1.28, 0.68, materials.hostile);
  body.position.y = 0.62;
  group.add(body);
  const head = block(0.45, 0.5, 0.45, materials.hostile);
  head.position.y = 1.15;
  group.add(head);
  const leftArm = block(0.2, 0.8, 0.2, materials.shadow);
  leftArm.position.set(-0.45, 0.8, 0);
  group.add(leftArm);
  const rightArm = block(0.2, 0.8, 0.2, materials.shadow);
  rightArm.position.set(0.45, 0.8, 0);
  group.add(rightArm);
  return group;
}

export function createRifleVisual(materials: ShooterMaterials): Group {
  const group = new Group();
  group.name = "rifle-visual";
  const barrel = shadowed(
    new Mesh(new CylinderGeometry(0.06, 0.06, 0.8, 6).rotateX(Math.PI / 2), materials.shadow),
    true,
  );
  barrel.position.z = 0.35;
  group.add(barrel);
  const stock = block(0.12, 0.12, 0.4, materials.shadow);
  stock.position.z = -0.15;
  group.add(stock);
  const magazine = block(0.12, 0.25, 0.08, materials.trim);
  magazine.position.set(0, -0.12, 0);
  group.add(magazine);
  return group;
}

export function createProjectileVisual(materials: ShooterMaterials): Mesh {
  return shadowed(new Mesh(new SphereGeometry(0.12, 4, 3), materials.trim), false);

